    "svc.7b": "សម្រាប់ផលិតផលថែរក្សាស្បែក គ្រឿងសម្អាង និងសម្រស់ឱសថធម្មជាតិផលិតនៅវៀតណាម — អង្ករ ឈូក រមៀត កាហ្វេ។ សម្រស់ក្នុងស្រុកពិតប្រាកដ កម្រលក់នៅបរទេស ស្វែងរក និងដឹកជញ្ជូន។ រយៈពេល៖ ១–៣ ថ្ងៃ។ អ្នកផ្ញើ៖ ឈ្មោះផលិតផល ឬរូបថត គោលដៅ។ (ច្បាប់អំពីវត្ថុរាវ និងពន្ធគយប្រែប្រួលតាមប្រទេស។)",
    "svc.3h": "រចនាស្ទីលពិធី &amp; ព្រឹត្តិការណ៍",
    "svc.3b": "សម្រាប់អាពាហ៍ពិពាហ៍ ពិធីស្លៀកអាវ áo dài ពិធីជប់លៀង ឬការថតរូប។ រូបរាងពេញលេញពីក្បាលដល់ជើង (១–២ ជម្រើស) ស្វែងរកតាមពិធីរបស់អ្នក។ រយៈពេល៖ គំនិតក្នុង ៣–៥ ថ្ងៃ — សូមសាកសួរមុន។ ចាប់ពី៖ ថ្លៃរចនាស្ទីលថេរ (ផ្តល់តម្លៃតាមសំណើ) ដកចេញពីការបញ្ជាទិញរបស់អ្នក។",
