    "services.cta": "មិនប្រាកដថាមួយណាសមនឹងអ្នក? ផ្ញើសារមក ហើយខ្ញុំនឹងណែនាំអ្នកទៅកន្លែងត្រឹមត្រូវដើម្បីចាប់ផ្តើម។",
    "sizing.eyebrow": "ទំហំ &amp; ភាពសម",
