    "sizing.vnxs": "<strong>VN XS / VN S</strong> — ទំហំក្នុងស្រុកតូចបំផុត សម្រាប់រូបរាងតូចល្អិតបំផុត (≈ US 00–0 · UK 2–4 · EU 30–32)។ បើ US XS រលុងចំពោះអ្នក សូមចាប់ផ្តើមនៅទីនេះ; បើមិនដូច្នេះទេ ចាប់ផ្តើមនៅ VN M។",
