    "sizing.n1": "ជួរស្តង់ដារនៅហាងម៉ូដ Saigon ភាគច្រើន ដូច្នេះជម្រើសទូលំទូលាយបំផុតនៅទីនេះ។ រំពឹងទុកប្រវែងខ្លី ស្មាចង្អៀត និងរន្ធដៃខ្ពស់ — ខ្ញុំសម្គាល់អ្វីៗដែលតូច ឬខ្លីជាពិសេស ហើយកត់សម្គាល់អ្វីដែលអាចកែបាន។",
