    "sizing.n4": "តាមរយៈម៉ាកឯកទេស ដែលរាប់បញ្ចូលទំហំ — Himistore (រហូតដល់ 6XL រង្វាស់អឺរ៉ុប) Cow's House និងអ្នករចនាដែលកាត់ M–5XL សម្រាប់រូបរាងអន្តរជាតិ។",
