    "sizing.fabric": "<strong>ក្រណាត់មានសារៈសំខាន់។</strong> កប្បាសពីម៉ាកក្នុងស្រុកថ្មីអាចរត់តូចជាងពីរទំហំធៀបនឹងក្រណាត់ linen ពី atelier បែបអឺរ៉ុប។ áo dài និងម៉ូដកាត់ដេរសមស្និទ្ធ។ ខ្ញុំបញ្ជាក់រង្វាស់សម្លៀកបំពាក់ពិតមុនយើងទិញ។",
    "sizing.brands": "<strong>ទំហំបន្ថែម ត្រូវបានគ្របដណ្តប់។</strong> Himistore (រហូតដល់ 6XL រង្វាស់ EU) ហាងម៉ូដសម្រាប់រូបរាងធាត់ដូចជា Cow's House និងអ្នករចនា Saigon ដែលកាត់ M–5XL សម្រាប់រូបរាងអន្តរជាតិ។ អ្នកមិនដែលទាយម្នាក់ឯងឡើយ។",
