    "process.intro": "លំដាប់ច្បាស់លាស់ និងបានពិចារណា។ អ្នកឃើញ និងអនុម័តអ្វីៗគ្រប់យ៉ាងមុនអ្នកបង់ពេញ។ តម្លៃពេញ និងការដឹកជញ្ជូនមាននៅក្នុងព័ត៌មានលម្អិតខាងក្រោម។",
