    "eco.b.the31": "Thời trang nữ hiện đại sử dụng vật liệu tái chế &amp; ít tác động hơn.",
    "eco.b.boo": "Streetwear với thực hành bền vững rõ ràng &amp; lượng người theo dõi nội địa mạnh mẽ.",
    "eco.b.hanoi": "Nhuộm tự nhiên, sợi bản địa, nghề thủ công của nghệ nhân (Hanoi).",
    "eco.cat.shoes": "Giày",
    "eco.b.tnbhsg": "Atelier Sài Gòn (thành lập 2018), giày da làm thủ công.",
    "eco.b.gogrunge": "Giày làm thủ công tại Sài Gòn, gìn giữ nghề đóng giày địa phương.",
    "eco.b.rens": "Giày sneaker tại Việt Nam làm từ vật liệu sáng tạo từ bã cà phê.",
    "eco.cat.eyewear": "Kính mắt",
    "eco.b.seeson": "Kính mắt Việt Nam làm từ acetate cellulose gốc sinh học, thiết kế hiện đại.",
    "eco.cat.accessories": "Phụ kiện &amp; túi xách",
    "eco.b.leinne": "Phụ kiện xa xỉ bền vững của Sài Gòn với bản sắc Việt đậm nét.",
    "eco.b.dongdong": "Túi từ vật liệu tái sử dụng — giảm thiểu, tái sử dụng, tái chế.",
    "eco.b.losilk": "Thời trang chậm made-in-Sài Gòn; khăn lụa tinh tế &amp; phụ kiện mềm mại.",
    "eco.vintage.h": "Đồ secondhand &amp; vintage cao cấp tại Sài Gòn",
    "eco.vintage.b": "Để mua sắm tuần hoàn, tôi có thể săn tìm đồ cũ tuyển chọn — ví dụ Maintwo (Q1), The Normal (Thủ Đức), 2Abnormal, Mayhem, Hebe Vintage, các cửa hàng Nhật Tảo (Q10), và các sạp ở chợ Bà Chiểu &amp; Chợ Bàn Cờ. Hàng hiệu secondhand qua ký gửi đã xác minh theo yêu cầu.",
    "eco.reading": "Bài đọc thêm",
    "inq.eyebrow": "Bắt đầu yêu cầu của bạn",
    "inq.h2": "Cho tôi biết bạn đang tìm gì",
    "inq.intro": "Bạn chia sẻ càng nhiều, tôi càng tìm được nhanh và gửi cho bạn một báo giá trung thực. Chưa cần thanh toán — đây chỉ đơn giản là khởi đầu của cuộc trò chuyện với Sài Gòn.",
