    "inq.sent": "✓ Đang mở ứng dụng email với mọi thứ đã điền sẵn. Hoặc nhắn tin cho tôi trên Instagram.",
    "inq.privacy": "Số đo, ảnh và địa chỉ của bạn được giữ riêng tư — chỉ dùng để tìm nguồn và gửi đơn hàng, không bao giờ chia sẻ hay bán đi.",
