    "look.eyebrow": "造型集",
    "look.h2": "精选作品",
    "look.intro": "正当时的越南单品，为世界各地的客户造型并寻获。你自己的造型集照片会径直嵌入这些画框中。",
    "look.t1": "重新演绎的 áo dài",
