    "look.t6": "场合穿搭",
    "trust.eyebrow": "静静被信赖",
    "trust.h2": "跨国下单，需要的是几分信任",
    "trust.intro": "我让这一切变得简单：付款前先让你看到实物，发货后送上物流追踪，全程以你的语言与你沟通。",
    "trust.s1h": "你先过目",
    "trust.s1b": "在你付款之前，先以照片确认实物。你所见，即你所得。",
    "trust.s2h": "全程可追踪",
    "trust.s2b": "包裹一发出便有物流单号，直至送到你门前持续更新。",
    "trust.s3h": "西贡的一个真实的人",
    "trust.s3b": "双语、就在当地、亲自走遍各家精品店——不是一个面目模糊的转售商。",
    "gift.eyebrow": "礼遇造型",
    "gift.h2": "把一整套西贡衣橱当作礼物送出",
    "gift.intro": "无论是为生日、婚礼，抑或仅是心之所至——择一档位，或自定金额，我都将亲自为您所赠之人悉心打点，再附上一纸心笺与一组兑换码。",
    "gift.1h": "初遇之礼",
    "gift.1b": "一份用于你所赠之人亲选其一单品的礼遇额度，由我寻得并送达。一份小巧而内敛奢华的心意。",
    "gift.buy": "送出此礼",
    "gift.tag": "最受喜爱",
    "gift.2h": "精选之礼",
    "gift.2b": "我们先以一次咨询为始，继而我会依其尺码，甄选三至五件单品成一小辑——送达其所在之处，无论身在何方。",
    "gift.3h": "工坊之礼",
    "gift.3b": "亲临其境的完整体验：造型搭配、单品采购，以及店内试穿，为那需要几分仪式感的场合而备。",
    "gift.included": "每一份礼物皆涵盖我的造型与采购服务，并附有用于单品本身的礼遇额度。运费将于您所赠之人兑换时另行报价。",
    "gift.pay": "倾向于分期支付？在提供此服务之处，PayPal Pay Later 可让你分期付款。",
    "gift.any": "或赠送任意金额 →",
    "gift.redeem": "已有礼品兑换码？立即兑换 →",
    "gift.note": "礼品通过电子邮件或私信安排，可通过银行转账、Wise、PayPal 或 PayPal Pay Later 安全付款。每份礼品均附带一张电子贺卡。",
    "eco.eyebrow": "有意识的寻源",
    "eco.h2": "美丽，且多一分善意",
    "eco.intro": "慢工胜于快销，本地优于远方，修复重于替换。在你愿意的地方，我会为你引荐越南最具匠心的制作者——并尽我所能让寻源保持低碳足迹。",
    "eco.1h": "电动出行，合并包裹",
    "eco.1b": "我在西贡的寻源行程都搭乘Xanh SM/Green SM的电动车——零尾气出行。把你的订单合并成一个包裹，意味着更少的运输次数与更低的运输碳排放。",
    "eco.2h": "有意识的越南品牌",
    "eco.2b": "我会为你指向越南领先的可持续品牌——有机与天然纤维、零废裁剪、天然染料、匠人供应链——当你选择经核实的可持续品牌时，还可享一笔小额服务费折扣。",
    "eco.3h": "循环与复古",
    "eco.3b": "更愿意循环消费？我会从西贡最优秀的精选二手店寻获高端二手与复古单品，还能为修补与改尺寸对接值得信赖的裁缝。",
    "eco.more": "在下方查看有意识的品牌、伦理理念与延伸阅读",
    "details.eyebrow": "细节详情",
    "details.h2": "你准备好时，一切尽在此处",
