    "price.formula": "单品价 = 门店价 + 基础费 + 服务费 + 国际运费",
    "price.formula.detail": "门店价 — 支付给精品店\n基础费 — 协调、处理与打包（每单100,000₫）\n服务费 — 寻源及越南境内运输（按件计，见下）\n国际运费 — 从西贡寄到你处的快递费用（按实收取）",
