    "eco.vintage.h": "西贡的高端二手与复古",
    "eco.vintage.b": "为循环购物，我可以为你搜寻精选二手店——例如Maintwo（D1）、The Normal（Thủ Đức）、2Abnormal、Mayhem、Hebe Vintage、Nhật Tảo（D10）一带的店铺，以及Bà Chiểu与Chợ Bàn Cờ的市集摊位。设计师二手可应询通过经核实的寄卖渠道获得。",
