    "nav.details": "التفاصيل",
    "nav.contact": "تواصل معنا",
    "a11y.language": "اللغة",
    "a11y.textsize": "حجم النص",
    "a11y.theme": "المظهر",
    "theme.light": "فاتح",
    "theme.dark": "داكن",
    "a11y.contrast": "تباين عالٍ",
