    "est.base": "الرسم الأساسي",
    "est.base.tip": "رسم ثابت قدره 100,000₫ لكل طلب يغطي التنسيق والمراسلة والتغليف بعناية. أما الشحن فيُحتسب بسعر التكلفة.",
