    "est.note": "هذا تقدير. سيتم تأكيد سعركِ النهائي (الشحن الدقيق، التوافر الحالي، سعر المتجر) من قبلي قبل أي دفع.",
    "look.eyebrow": "دفتر الإطلالات",
    "look.h2": "أعمال مختارة",
    "look.intro": "قطع فيتنامية رائجة، منسّقة وموردة لعميلات حول العالم. صور دفتر إطلالاتكِ الخاصة ستندرج ضمن هذه الإطارات.",
    "look.t1": "áo dài بحُلّة جديدة",
    "look.t2": "كوكيت / فتاة ناعمة",
    "look.t3": "من المكتب إلى السهرة",
