    "inq.looking.ph": "Un lien, une marque, ou simplement l'ambiance — coquette, áo dài-moderne, vintage, beauté…",
    "inq.size": "Taille &amp; mensurations",
    "inq.timeline": "Délai",
    "inq.inspo": "Liens d'inspiration (facultatif)",
    "inq.notes": "Autre chose",
    "inq.submit": "Envoyer ma demande",
