    "journey.3h": "Взгляд",
    "journey.3b": "Именно то, что вы получите — сфотографировано и проверено.",
    "journey.4h": "Доверие",
    "journey.4b": "Прозрачный процесс — честная цена, отслеживание, забота.",
    "journey.5h": "Носить",
    "journey.5b": "Тщательно выбранная вещь из Вьетнама — в любой точке мира.",
    "nav.about": "О нас",
    "nav.services": "Услуги",
