    "eco.vintage.h": "Премиальный секонд-хенд и винтаж в Сайгоне",
    "eco.vintage.b": "Для циркулярного шопинга я могу искать кураторские комиссионки — например Maintwo (D1), The Normal (Thủ Đức), 2Abnormal, Mayhem, Hebe Vintage, магазины Nhật Tảo (D10) и рыночные прилавки на Bà Chiểu и Chợ Bàn Cờ. Дизайнерский секонд-хенд через проверенную комиссию — по запросу.",
