    "theme.mono": "モノ",
    "sizing.fine": "詳細 — 小柄向けサイズ、素材＆大きめサイズ表記",
    "sizing.vnxs": "<strong>VN XS / VN S</strong> — 最も小柄な方向けの、現地で最も小さいサイズです（およそ US 00–0 · UK 2–4 · EU 30–32）。US XS がゆるめに感じる方はここから、そうでなければ VN M からお試しください。",
