    "est.deposit": "订金——开始时支付",
    "est.deposit.tip": "包含单品、服务费与基础费——所有我今天就能精确计算的部分。您确认实拍照片后支付，我便可立即购买。",
    "est.balance": "尾款——发货前支付",
