    "est.compare": "对比第二个收货地",
    "est.compare.tip": "如果这件衣服可以寄到不止一个地址——第二个家、海外的家人，或您当月所在的城市——请同时选择两地，并排查看两个总价。运费是估算中变动最大的部分。",
    "est.shipto2": "第二个收货地",
