    "est.cmp.h": "对比两个收货地",
    "est.cmp.sub": "同样的单品、同样的服务费——只有运费不同。选一个，或两个都发给我，我会确认每条路线的真实快递价格。",
    "est.cmp.lower": "估算更低",
    "est.cmp.use": "寄到这里",
    "est.cmp.cheaperby": "更便宜约",
    "est.cmp.even": "两条路线估算相同——选您更方便收货的那个。",
    "est.cmp.duty": "目的国的进口关税与清关费用未包含在内，且各国不同——较便宜的路线在完税后仍可能更贵。付款前我会提醒您。",
    "est.cmp.custom": "超过 10 公斤的包裹需单独报价，我会手动计算两条路线——发送估算后，我会把 {a} 和 {b} 一起报给您。",
    "est.cmp.nopieces": "运费会在单品确定后加入——先添加一件单品即可对比两条路线。",
    "est.back": "戻る",
    "est.q.weight": "おおよそのサイズで大丈夫です — 発送前に正確な重量を確認します。衣類の国際送料は決して安くありません：最近の0.5–1 kgの荷物で1,950,000₫かかりました。厚手の生地は見た目より重くなります。",
    "est.complex.tip": "希少品や限定リリース、街じゅうの複数店舗を巡る調達、短い納期、または調達開始後の多数の変更がある場合にのみ加算されます — 必ず事前にご相談し、後から不意に請求することはありません。",
    "est.green": "グリーンショッピング — サステナブルなブランドを選ぶ（サービス料 −10%）",
    "est.green.tip": "グリーンな買い物には意味があります：環境負荷が低く、地元で作られ、循環型のアイテムを選ぶことは、廃棄を減らし、水を節約し、ベトナムの職人を支えます。認証されたサステナブルなブランドをお選びいただければ、サービス料を10%割引します。グリーンな暮らしについては treehugger.com をご覧ください。",
    "est.see": "見積もりを見る",
