    "est.greenline": "グリーンショッピング割引",
    "est.restart": "最初からやり直す",
    "dir.eyebrow": "ディレクトリ",
    "dir.h2": "サイゴンファッションディレクトリ",
    "dir.lead": "この街のファッションの名店を映す、生きた地図です — 検証済みの300軒のブティック、アトリエ、デザイナーズブランド、マーケットを、地区・価格帯・カテゴリーで絞り込めます。すべての調達依頼の土台となるものです。",
    "dir.legend": "軒 — 円の面積 ∝ 店舗数",
    "dir.cap": "9つの地区に徒歩で巡れる207軒があり、さらに43軒がオンラインまたはマルチブランドです — サイゴンで合わせて250軒。",
    "dir.s1": "軒を収録",
    "dir.s2": "サイゴン内",
