    "est.customquote": "個別見積もり",
    "est.plusship": " ＋ 送料",
    "est.customhaul": " ＋ 送料（個別見積もり・10kg以上）",
    "est.acc.sum": "この見積もりの精度は？",
    "est.acc.p1": "<strong>〜95%は確定的です。</strong> ご入力の商品価格、わたしのサービス料、定額の基本料金は、すべて決まった計算式に従います — 入力内容に対する計算は正確で、ベトナム国内の送料はすでに含まれています。",
    "est.acc.complex": "<strong>加算され得る項目は1つだけです：</strong>希少品や限定リリース、複数店舗を巡る調達、短い納期に対する一律200,000₫。必ず事前にご相談したうえでのみ加算し、最終見積もりで不意に増えることはありません。",
    "est.acc.p2": "<strong>残りの〜5%は、お支払い前に確定します：</strong> 当日の実際の店頭価格、正確な国際送料（重量と配送業者）、リアルタイムの為替レート、在庫状況、そしてお住まいの国での関税や輸入税。",
    "est.acc.p3": "最終見積もりをご承認いただくまで、料金は一切発生しません。",
    "ask.eyebrow": "よくあるご質問",
