    "ask.intro": "サイズ、関税、配送、そして真贋について、正直にお答えします——そのほかのことも、メッセージひとつでいつでも。",
    "journey.eyebrow": "旅は、ひとつの物語",
    "journey.h2": "夢から<em>クローゼット</em>へ",
    "journey.intro": "ひと目でたどる物語のすべて——五つの静かな拍、夢想から、あなたの手の中の一着へ。",
    "journey.1h": "訪れる",
    "journey.1b": "やわらかな夢の中へ——たおやかなラベンダーの世界。",
    "journey.2h": "出会う",
    "journey.2b": "サイゴンの、実在するひとりの人——バイリンガルで、いつもそばに。",
    "journey.3h": "見る",
    "journey.3b": "受け取るものを、そのままに——撮影し、検めて。",
    "journey.4h": "信じる",
    "journey.4b": "透明なプロセス——誠実な価格、追跡、そして心くばり。",
    "journey.5h": "纏う",
    "journey.5b": "心を込めて選んだベトナムの一着を、世界のどこへでも。",
