    "eco.b.metiseko": "GOTS-ऑर्गैनिक कॉटन &amp; वियतनामी रेशम, कम-प्रभाव वाले रंग, छोटे बैच (Hội An)।",
    "eco.b.moidien": "सायगॉन डिज़ाइनर लेबल; टिकाऊपन &amp; \"बेहतर ख़रीदो, ज़्यादा देर तक रखो\"।",
