    "eco.b.archive": "Boro / Sashiko मरम्मत &amp; अपसाइक्लिंग — एक-के-एक परिधान (Đà Lạt)।",
    "eco.b.the31": "रीसाइकल्ड &amp; कम-प्रभाव वाली सामग्री से बने आधुनिक महिला परिधान।",
    "eco.b.boo": "दिखती टिकाऊपन प्रथाओं &amp; मज़बूत स्थानीय अनुयायियों वाला स्ट्रीटवेअर।",
