    "eco.b.gogrunge": "स्थानीय जूता-कला को सहेजते सायगॉन के हाथ से बने जूते।",
    "eco.b.rens": "कॉफ़ी-ग्राउंड सामग्री नवाचार से बने वियतनाम-आधारित स्नीकर्स।",
