    "eco.b.dongdong": "दोबारा इस्तेमाल की गई सामग्री से बने बैग — घटाओ, दोबारा उपयोग करो, रीसाइकल करो।",
    "eco.b.losilk": "सायगॉन में बना स्लो फ़ैशन; उत्कृष्ट रेशमी स्कार्फ़ &amp; कोमल एक्सेसरीज़।",
