    "eco.vintage.b": "सर्कुलर ख़रीदारी के लिए मैं चुनिंदा थ्रिफ़्ट ढूँढ सकती हूँ — जैसे Maintwo (D1), The Normal (Thủ Đức), 2Abnormal, Mayhem, Hebe Vintage, Nhật Tảo (D10) की दुकानें, और Bà Chiểu &amp; Chợ Bàn Cờ के बाज़ार स्टॉल। माँगने पर प्रमाणित कंसाइनमेंट के ज़रिए डिज़ाइनर सेकंडहैंड।",
    "eco.reading": "आगे की पढ़ाई",
