    "inq.intro": "आप जितना ज़्यादा साझा करेंगी, उतनी ही जल्दी मैं उसे ढूँढकर एक ईमानदार क़ीमत भेज सकूँगी। अभी कोई भुगतान नहीं — यह तो बस साइगॉन के साथ बातचीत की शुरुआत है।",
