    "inq.privacy": "आपकी माप, तस्वीरें, और पता निजी रहते हैं — केवल आपके ऑर्डर को सोर्स और भेजने के लिए इस्तेमाल होते हैं, कभी साझा या बेचे नहीं जाते।",
    "inq.response": "मैं आमतौर पर 1–2 कार्यदिवसों के भीतर जवाब देती हूँ (सायगॉन समय, GMT+7)।",
    "inq.or": "सीधे संपर्क करना पसंद करेंगी? Instagram, TikTok, और ईमेल सभी खुले हैं।",
