    "hero.eyebrow": "อะตอลิเยร์จัดสไตล์ &amp; เสาะหาสินค้าจากไซ่ง่อน",
    "hero.h1": "สไตล์ไซ่ง่อน<br/>ส่งตรงถึงคุณทุกที่ทั่วโลก",
    "hero.lead": "ฉันเสาะหาสินค้าแฟชั่นและความงามเวียดนามที่หาได้ยากจากนครโฮจิมินห์ให้แก่ลูกค้าในต่างแดน",
