    "trust.intro": "ฉันทำให้เรียบง่าย: ฉันให้คุณเห็นสินค้าจริงก่อนชำระเงิน แจ้งหมายเลขติดตามเมื่อจัดส่ง และสื่อสารด้วยภาษาของคุณตลอดทั้งกระบวนการ",
