    "gift.intro": "ไม่ว่าจะเป็นวันเกิด งานแต่งงาน หรือเพียงเพราะอยากมอบให้ — เลือกระดับของขวัญหรือกำหนดจำนวนเงินด้วยตัวคุณเอง แล้วฉันจะดูแลผู้รับของคุณด้วยตนเอง จากนั้นจึงส่งข้อความและรหัสสำหรับใช้รับสิทธิ์",
    "gift.1h": "The Discovery",
    "gift.1b": "เครดิตสำหรับชิ้นงานหนึ่งชิ้นที่ผู้รับเป็นผู้เลือก ซึ่งฉันจะเสาะหาและจัดส่งให้ ของขวัญเล็กๆ ที่หรูหราอย่างเงียบงาม",
    "gift.buy": "มอบสิ่งนี้เป็นของขวัญ",
    "gift.tag": "ขอกันมากที่สุด",
    "gift.2h": "The Edit",
    "gift.2b": "เราเริ่มต้นด้วยการปรึกษา จากนั้นฉันจะคัดสรรชุดชิ้นงานเล็ก ๆ จำนวนสามถึงห้าชิ้นในไซซ์ของพวกเขา จัดส่งไปยังที่ใดก็ตามที่พวกเขาอยู่",
    "gift.3h": "The Atelier",
    "gift.3b": "ประสบการณ์เต็มรูปแบบแบบพบหน้า ทั้งการจัดสไตล์ การจัดหา และการลองสวมในร้าน สำหรับโอกาสที่ควรค่าแก่พิธีรีตองเล็ก ๆ",
