    "eco.eyebrow": "การเสาะหาอย่างใส่ใจ",
    "eco.h2": "งดงาม และอ่อนโยนขึ้นอีกนิด",
    "eco.intro": "ช้าดีกว่าเร็ว ท้องถิ่นดีกว่าไกลตัว ซ่อมแซมดีกว่าเปลี่ยนใหม่ หากคุณปรารถนา ฉันจะแนะนำคุณให้รู้จักผู้สร้างสรรค์ที่ใส่ใจที่สุดของเวียดนาม — และฉันจะเสาะหาอย่างกระทบต่อสิ่งแวดล้อมน้อยที่สุดเท่าที่จะทำได้",
    "eco.1h": "เดินทางด้วยรถไฟฟ้า พัสดุน้อยลง",
    "eco.1b": "การเดินทางเสาะหาสินค้าในไซ่ง่อนของฉันใช้ยานยนต์ไฟฟ้าผ่าน Xanh SM / Green SM — การเดินทางปลอดไอเสีย การรวมออเดอร์ของคุณเป็นพัสดุเดียวหมายถึงการส่งน้อยลงและคาร์บอนจากการขนส่งต่ำลง",
    "eco.2h": "แบรนด์เวียดนามที่ใส่ใจ",
    "eco.2b": "ฉันจะแนะนำคุณให้รู้จักป้ายยั่งยืนชั้นนำของเวียดนาม — เส้นใยออร์แกนิกและจากธรรมชาติ การตัดเย็บแบบไร้ขยะ สีย้อมธรรมชาติ ห่วงโซ่อุปทานงานหัตถกรรม — พร้อมส่วนลดค่าบริการเล็กน้อยเมื่อคุณเลือกแบรนด์ยั่งยืนที่ผ่านการรับรอง",
    "eco.3h": "หมุนเวียน &amp; วินเทจ",
    "eco.3b": "ชอบช้อปแบบหมุนเวียนใช่ไหม? ฉันเสาะหาของมือสองและวินเทจระดับไฮเอนด์จากร้านคัดสรรที่ดีที่สุดของไซ่ง่อน และจับคู่ชิ้นงานกับช่างตัดเสื้อที่ไว้ใจได้เพื่อซ่อมและแก้ไซส์",
    "eco.more": "ดูแบรนด์ที่ใส่ใจ จริยธรรม &amp; แหล่งอ่านเพิ่มเติมด้านล่าง",
    "details.eyebrow": "รายละเอียด",
    "details.h2": "ทุกรายละเอียด เมื่อคุณพร้อม",
    "acc.pricing": "ราคา &amp; ค่าธรรมเนียม",
    "price.formula": "ราคาสินค้า = ราคาร้าน + ค่าธรรมเนียมพื้นฐาน + ค่าบริการ + ค่าจัดส่งระหว่างประเทศ",
    "price.formula.detail": "ราคาร้าน — จ่ายให้บูทีค\nค่าธรรมเนียมพื้นฐาน — การประสานงาน ดำเนินการ &amp; แพ็ก (100,000₫ ต่อออเดอร์)\nค่าบริการ — การเสาะหา &amp; การจัดส่งภายในเวียดนาม (ต่อชิ้น ดูด้านล่าง)\nค่าจัดส่งระหว่างประเทศ — ค่าขนส่งจากไซ่ง่อนถึงคุณ (ตามจริง)",
    "tier.1r": "สินค้าต่ำกว่า 2,000,000₫",
