    "price.base.h": "ค่าธรรมเนียมพื้นฐาน · 100,000₫ / ออเดอร์",
    "price.base.b": "ค่าธรรมเนียมเหมาจ่ายต่อออเดอร์ ครอบคลุมการพูดคุย ประสานงาน และแพ็กอย่างพิถีพิถัน ค่าจัดส่งคิดตามจริง — ไม่มีบวกกำไรแอบแฝง",
    "price.complex.h": "เสาะหาแบบซับซ้อน · + เริ่มต้น 200,000₫",
    "price.complex.b": "เพิ่มเฉพาะกรณีของหายากหรือคอลเล็กชันลิมิเต็ด การตามหาหลายร้าน เดดไลน์กระชั้น หรือมีการเปลี่ยนแปลงมากหลังเริ่มเสาะหา ตกลงกับคุณล่วงหน้า",
    "price.min": "ยอดขั้นต่ำแบบยืดหยุ่น: คำสั่งซื้อส่วนใหญ่อยู่ที่ราว 100–150 USD+ (หรือหลายชิ้น) เพื่อให้ประสบการณ์นี้คุ้มค่าสำหรับเราทั้งสองฝ่าย คุณจะได้เห็นการแจกแจงราคาอย่างชัดเจนก่อนซื้อทุกครั้ง",
    "t2.1h": "ช้อปปิ้งส่วนตัวมาตรฐาน",
    "t2.1b": "สั่งซื้อออนไลน์แล้วจัดส่งถึงคุณ ค่าธรรมเนียมพื้นฐาน + ค่าบริการต่อชิ้น รวมค่าจัดส่งภายในเวียดนาม วิธีสั่งซื้อแบบทั่วไปในชีวิตประจำวัน",
    "t2.2h": "ลองสินค้า &amp; ฟิตติ้งในร้าน",
    "t2.2b": "เพื่อความมั่นใจยิ่งขึ้นก่อนซื้อ ฉันจะไปที่บูทีคด้วยตัวเอง — หยิบไซซ์ ดูแลการลองสินค้า และส่งโน้ตเรื่องความพอดีพร้อมภาพแบบสดๆ 500,000₫/hr ขั้นต่ำ 2 ชั่วโมง พร้อมมัดจำ 500,000₫ เพื่อจองช่วงเวลาของคุณ (นำไปหักกับค่าบริการ) เหมาะสำหรับคำสั่งซื้อที่ต้องการความพอดีเป็นพิเศษหรือมูลค่าสูง (งบที่วางไว้ราว 200–300 USD+)",
    "t2.3h": "ออเดอร์ซับซ้อน / ดูแลใกล้ชิด",
    "t2.3b": "คำขอที่หายาก เร่งด่วน หรือต้องไปหลายร้าน ค่าบริการมาตรฐานบวกค่าความซับซ้อน (แบบเหมาหรือเปอร์เซ็นต์เพิ่มเล็กน้อย) ตกลงกันล่วงหน้าเสมอ มัดจำการจองที่ไม่สามารถขอคืนได้เพื่อยืนยันคำสั่งซื้อที่จริงจัง",
    "acc.shipping": "การจัดส่ง &amp; ศุลกากร",
    "ship.intro": "พัสดุชิ้นเล็กสามารถประเมินได้จากตารางด้านล่าง สำหรับคำสั่งซื้อขนาดใหญ่ที่รวมหลายชิ้น ค่าจัดส่งสุดท้ายขึ้นอยู่กับน้ำหนักหลังแพ็ก ขนาด และปลายทาง สำหรับออเดอร์หนัก — 10kg+ / 22lb+ — ฉันจะยืนยันแผนการแพ็กที่ดีที่สุดและใบเสนอราคาขนส่งก่อนจัดส่ง และอาจแบ่งพัสดุออกเป็นหลายกล่องเมื่อปลอดภัยหรือประหยัดกว่า",
