    "eco.b.leinne": "เครื่องประดับลักชัวรียั่งยืนไซ่ง่อนที่มีเอกลักษณ์เวียดนามชัดเจน",
    "eco.b.dongdong": "กระเป๋าจากวัสดุรีไซเคิล — ลด ใช้ซ้ำ รีไซเคิล",
    "eco.b.losilk": "สโลว์แฟชั่นเมดอินไซ่ง่อน ผ้าพันคอไหมประณีต &amp; เครื่องประดับนุ่มนวล",
    "eco.vintage.h": "ของมือสอง &amp; วินเทจระดับไฮเอนด์ในไซ่ง่อน",
    "eco.vintage.b": "สำหรับการช้อปแบบหมุนเวียน ฉันตามหาร้านคัดสรรได้ — เช่น Maintwo (D1), The Normal (Thủ Đức), 2Abnormal, Mayhem, Hebe Vintage, ร้านย่าน Nhật Tảo (D10) และแผงตลาดที่ Bà Chiểu &amp; Chợ Bàn Cờ ของมือสองดีไซเนอร์ผ่านร้านฝากขายที่ตรวจสอบแล้วตามคำขอ",
