    "inq.intro": "ยิ่งคุณบอกมากเท่าไร ฉันก็ยิ่งหาได้เร็วและส่งใบเสนอราคาอย่างซื่อตรงได้เร็วเท่านั้น ยังไม่ต้องชำระเงิน — นี่เป็นเพียงจุดเริ่มต้นของการสนทนากับไซ่ง่อนเท่านั้น",
