    "eco.cat.accessories": "اکسسوری و کیف",
    "eco.b.leinne": "اکسسوری‌های لوکس پایدار سایگونی با هویتی نیرومند ویتنامی.",
    "eco.b.dongdong": "کیف از مواد بازاستفاده‌شده — کاهش، بازاستفاده، بازیافت.",
    "eco.b.losilk": "مد آهستهٔ ساخت سایگون؛ روسری‌های ابریشمی ظریف و اکسسوری‌های لطیف.",
    "eco.vintage.h": "کالاهای دست‌دوم و وینتیج گران‌قیمت در سایگون",
    "eco.vintage.b": "برای خرید چرخه‌ای می‌توانم به جست‌وجوی فروشگاه‌های منتخب دست‌دوم بپردازم — مثلاً Maintwo (D1)، The Normal (Thủ Đức)، 2Abnormal، Mayhem، Hebe Vintage، فروشگاه‌های Nhật Tảo (D10)، و دکه‌های بازار در Bà Chiểu و Chợ Bàn Cờ. کالاهای دست‌دوم طراحان از طریق امانت‌فروشی تأییدشده، با درخواست.",
    "eco.reading": "مطالعهٔ بیشتر",
